# Shared enums and constants.
# Trace:
#   - DAT--1 GridMap.Direction
#   - DAT--4 Direction enum
#   - Used by CMP--2, CMP--3, CMP--4, CMP--5, CMP--6, CMP--9

class Direction:
    NORTH = 0
    EAST = 1
    SOUTH = 2
    WEST = 3


def direction_to_dx_dy(direction):
    # DAT--4: neighbor directions on 4x8 grid (x in [0..3], y in [0..7])
    if direction == Direction.NORTH:
        return 0, 1
    if direction == Direction.EAST:
        return 1, 0
    if direction == Direction.SOUTH:
        return 0, -1
    if direction == Direction.WEST:
        return -1, 0
    return 0, 0


def opposite_direction(direction):
    return (direction + 2) % 4

# Simple timing helpers.
# Trace:
#   - Used for mapping_time_budget_s (CMP--2, FSM--1)
#   - Used for stall timeouts (CMP--5, CMP--9, DAT--6)

import utime


def monotonic_ms():
    # Monotonic-ish milliseconds since boot (MicroPython).
    return utime.ticks_ms()


def elapsed_ms(start_ms):
    return utime.ticks_diff(monotonic_ms(), start_ms)

# ExternalStatusLogger implementation. # Trace: # - CMP--13 ExternalStatusLogger # - CMP--10 uses for ExternalRunStatusOutput # - CMP--6, CMP--2, CMP--5, CMP--9 use for diagnostics
class ExternalStatusLogger: def __init__(self): # No external sink besides console in this implementation. # Future extensions could write to file or UART. pass
def log(self, message, component="GENERIC"): # CMP--13: Execution - write status to console # DerivedFrom LL-RUN-1.2.4 print("[%s] %s" % (component, message))
def error(self, message, component="GENERIC"): self.log("ERROR: " + message, component=component)
def warn(self, message, component="GENERIC"): self.log("WARN: " + message, component=component)

# ConfigurationManager implementation.
# Trace:
#   - CMP--1 ConfigurationManager component
#   - Derived from DAT--5 (configuration parameters and validation)
#
# Provides:
#   - Safe defaults if file missing or invalid (CMP--1 Failures)
#   - Read-only accessors used by other components.

import ujson
import os


class ConfigurationManager:
    CONFIG_PATH = "config.json"  # simple JSON instead of INI for MicroPython

    def __init__(self, logger):
        self._logger = logger
        self._config = {}
        self._flags = {
            "CONFIG_DEFAULT_USED": False,
            "CONFIG_PARAM_CLAMPED": False,
        }
        # Defaults derived from DAT--5
        self._defaults = {
            "timing": {
                "mapping_time_budget_s": 300,
                "stall_timeout_per_cell_s": 3.0,
                "stall_max_retries": 3,
            },
            "speed": {
                "exploration_trans_speed_cm_s": 40,
                "exploration_rot_speed_deg_s": 90,
                "second_run_trans_speed_cm_s": 80,
                "second_run_rot_speed_deg_s": 180,
                "max_motor_speed_exploration": 70,
                "max_motor_speed_second_run": 85,
            },
            "sensor_filter": {
                "ultrasonic_filter_window": 5,
                "ir_confirm_count": 3,
                "ir_clear_count": 3,
            },
            "safety": {
                "braking_distance_table": None,  # simplified; see _stopping_distance_cm
                "safety_margin_cm": 2.0,
                "ultrasonic_min_valid_cm": 2.0,
                "ultrasonic_max_valid_cm": 100.0,
            },
            "env": {
                "cell_size_cm": 17.2,
                "wall_thickness_cm": 1.6,
                "robot_radius_cm": 5.5,
                "uncertainty_margin_cm": 4.0,
            },
        }

    # CMP--1 Execution: load and validate configuration
    def load(self):
        if not self._file_exists(self.CONFIG_PATH):
            self._logger.warn(
                "Configuration file missing. Using safe defaults.",
                component="CMP--1",
            )
            self._flags["CONFIG_DEFAULT_USED"] = True
            self._config = self._defaults.copy()
            return

        try:
            with open(self.CONFIG_PATH, "r") as f:
                raw = f.read()
            cfg = ujson.loads(raw)
        except Exception as exc:
            self._logger.warn(
                "Failed to parse config file (%s). Using defaults." % exc,
                component="CMP--1",
            )
            self._flags["CONFIG_DEFAULT_USED"] = True
            self._config = self._defaults.copy()
            return

        # Merge and validate sections
        self._config = {}
        for section in self._defaults:
            sec_defaults = self._defaults[section]
            raw_sec = cfg.get(section, {})
            validated = {}
            for key in sec_defaults:
                value = raw_sec.get(key, sec_defaults[key])
                validated[key] = self._validate_key(section, key, value, sec_defaults[key])
            self._config[section] = validated

        self._logger.log("Configuration loaded and validated.", component="CMP--1")

    def _file_exists(self, path):
        try:
            s = os.stat(path)
            return s[0] & 0x4000 == 0 or True
        except OSError:
            return False

    # DAT--5: validation rules
    def _validate_key(self, section, key, value, default):
        clamped = False
        if section == "timing" and key == "mapping_time_budget_s":
            if not isinstance(value, (int, float)) or value <= 0 or value > 300:
                value = 300
                clamped = True
        elif section == "timing" and key == "stall_timeout_per_cell_s":
            if not isinstance(value, (int, float)) or value <= 0:
                value = default
                clamped = True
        elif section == "timing" and key == "stall_max_retries":
            if not isinstance(value, int) or value < 0 or value > 10:
                value = default
                clamped = True
        elif section == "speed":
            if not isinstance(value, (int, float)) or value <= 0 or value > 200:
                value = default
                clamped = True
        elif section == "sensor_filter":
            if not isinstance(value, int) or value < 1 or value > 10:
                value = default
                clamped = True
        elif section == "safety":
            if key == "safety_margin_cm":
                if not isinstance(value, (int, float)) or value <= 0:
                    value = default
                    clamped = True
            elif key in ("ultrasonic_min_valid_cm", "ultrasonic_max_valid_cm"):
                if not isinstance(value, (int, float)) or value < 0:
                    value = default
                    clamped = True
        elif section == "env":
            if not isinstance(value, (int, float)) or value <= 0:
                value = default
                clamped = True

        if clamped:
            self._flags["CONFIG_PARAM_CLAMPED"] = True
            self._logger.warn(
                "Config parameter %s.%s clamped or defaulted." % (section, key),
                component="CMP--1",
            )
        return value

    # Accessors for other components (CMP--1 Transmit signals)
    # ExplorationTimingAndSpeedConfig - for CMP--2
    def get_mapping_time_budget_s(self):
        return self._config["timing"]["mapping_time_budget_s"]

    def get_exploration_speeds(self):
        return (
            self._config["speed"]["exploration_trans_speed_cm_s"],
            self._config["speed"]["exploration_rot_speed_deg_s"],
        )

    def get_second_run_speeds(self):
        return (
            self._config["speed"]["second_run_trans_speed_cm_s"],
            self._config["speed"]["second_run_rot_speed_deg_s"],
        )

    def get_stall_config(self):
        return (
            self._config["timing"]["stall_timeout_per_cell_s"],
            self._config["timing"]["stall_max_retries"],
        )

    def get_sensor_filter_config(self):
        sf = self._config["sensor_filter"]
        safety = self._config["safety"]
        return {
            "ultrasonic_filter_window_size": sf["ultrasonic_filter_window"],
            "ir_confirm_count": sf["ir_confirm_count"],
            "ir_clear_count": sf["ir_clear_count"],
            "min_valid_cm": safety["ultrasonic_min_valid_cm"],
            "max_valid_cm": safety["ultrasonic_max_valid_cm"],
        }

    def get_env_config(self):
        env = self._config["env"]
        return {
            "cell_size_cm": env["cell_size_cm"],
            "wall_thickness_cm": env["wall_thickness_cm"],
            "robot_radius_cm": env["robot_radius_cm"],
            "uncertainty_margin_cm": env["uncertainty_margin_cm"],
        }

    def get_safety_config(self):
        safety = self._config["safety"]
        env = self._config["env"]
        return {
            "safety_margin_cm": safety["safety_margin_cm"],
            "ultrasonic_min_valid_cm": safety["ultrasonic_min_valid_cm"],
            "ultrasonic_max_valid_cm": safety["ultrasonic_max_valid_cm"],
            "robot_radius_cm": env["robot_radius_cm"],
            "uncertainty_margin_cm": env["uncertainty_margin_cm"],
        }

    def get_speed_limits(self):
        sp = self._config["speed"]
        return {
            "max_motor_speed_exploration": sp["max_motor_speed_exploration"],
            "max_motor_speed_second_run": sp["max_motor_speed_second_run"],
        }

    def get_flags(self):
        return self._flags

    # Simple braking distance approximation (DAT--6 note: simplified)
    def stopping_distance_cm(self, speed_cm_s):
        # In real implementation, use braking_distance_table (DAT--6).
        # Here approximate with linear scaling: distance = k * speed
        k = 0.05  # 0.05 s stopping at full effort
        return speed_cm_s * k

# MapManager implementation.
# Trace:
#   - CMP--3 MapManager
#   - DAT--1 GridMap structure
#   - DAT--2 wall detection and cell classification
#   - DAT--3 frontier and reachability queries (partial; planner handles BFS)

from core.data_structures import GridMap, OccupancyState
from core.enums import Direction, direction_to_dx_dy, opposite_direction


class MapManager:
    def __init__(self, config_mgr, logger):
        self._cfg = config_mgr
        self._logger = logger
        self._map = GridMap()
        self._initialized = False

    # CMP--3 Execution: initialization
    def initialize_start_and_goal_regions(self):
        # DAT--1: set goal region cells (2,6),(2,7),(3,6),(3,7)
        for x in range(4):
            for y in range(8):
                c = self._map.cells[x][y]
                c.occupancy = OccupancyState.UNKNOWN
                c.walls.wall_north = False
                c.walls.wall_east = False
                c.walls.wall_south = False
                c.walls.wall_west = False
                c.is_start_region = False
                c.is_goal_region = False
                c.unknown_neighbor_count = 0

        self._map.cells[2][6].is_goal_region = True
        self._map.cells[2][7].is_goal_region = True
        self._map.cells[3][6].is_goal_region = True
        self._map.cells[3][7].is_goal_region = True

    def initialize_start_pose(self, heading):
        # DAT--1: start cell (0,0)
        self._map.current_x = 0
        self._map.current_y = 0
        self._map.current_heading = heading
        start_cell = self._map.cells[0][0]
        start_cell.occupancy = OccupancyState.FREE
        start_cell.is_start_region = True
        self._recompute_unknown_neighbors_all()
        self._initialized = True
        self._logger.log("Map initialized with start pose.", component="CMP--3")

    # Interfaces for CMP--2:
    def get_current_pose_info(self):
        return (self._map.current_x, self._map.current_y, self._map.current_heading)

    def set_current_pose(self, x, y, heading):
        if 0 <= x < 4 and 0 <= y < 8:
            self._map.current_x = x
            self._map.current_y = y
            self._map.current_heading = heading
            self._logger.log(
                "Pose updated to (%d,%d) heading %d" % (x, y, heading),
                component="CMP--3",
            )

    def get_grid_map(self):
        # CMP--3 -> CMP--4 GridMapAndWalls (read-only)
        return self._map

    # DAT--2: update map from scan
    def update_from_scan(self, front_distance_cm, ir_left_obstacle, ir_right_obstacle):
        if not self._initialized:
            return
        x = self._map.current_x
        y = self._map.current_y
        heading = self._map.current_heading
        cell = self._map.cells[x][y]

        env = self._cfg.get_env_config()
        safety = self._cfg.get_safety_config()

        cell_size = env["cell_size_cm"]
        wall_thickness = env["wall_thickness_cm"]
        robot_radius = env["robot_radius_cm"]
        uncertainty_margin = env["uncertainty_margin_cm"]
        safety_margin = safety["safety_margin_cm"]

        # DAT--2: d_expected and T_front
        d_expected = (cell_size / 2.0) - robot_radius - (wall_thickness / 2.0)
        t_front = d_expected + safety_margin - uncertainty_margin

        if front_distance_cm is not None and front_distance_cm <= t_front:
            self._set_wall(x, y, heading)

        # Side walls from IR, assign based on current heading.
        if ir_left_obstacle:
            left_dir = self._left_of(heading)
            self._set_wall(x, y, left_dir)
        if ir_right_obstacle:
            right_dir = self._right_of(heading)
            self._set_wall(x, y, right_dir)

        # Cell classification (simplified per DAT--2)
        walls_count = self._count_walls(cell)
        if walls_count <= 3:
            cell.occupancy = OccupancyState.FREE
        else:
            # Enforce max 3 walls; ignore fourth detection
            self._logger.warn(
                "Attempted to set 4th wall at (%d,%d); ignoring last evidence." % (x, y),
                component="CMP--3",
            )
            # Do not change walls here (CMP--3 Failures)
        self._recompute_unknown_neighbors_all()

    def _count_walls(self, cell):
        w = cell.walls
        return int(w.wall_north) + int(w.wall_east) + int(w.wall_south) + int(w.wall_west)

    # DAT--1 wall consistency rules
    def _set_wall(self, x, y, direction):
        if not (0 <= x < 4 and 0 <= y < 8):
            return
        cell = self._map.cells[x][y]
        # Never remove walls; only set to True
        if direction == Direction.NORTH:
            if y < 7:
                cell.walls.wall_north = True
                self._map.cells[x][y + 1].walls.wall_south = True
        elif direction == Direction.SOUTH:
            if y > 0:
                cell.walls.wall_south = True
                self._map.cells[x][y - 1].walls.wall_north = True
        elif direction == Direction.EAST:
            if x < 3:
                cell.walls.wall_east = True
                self._map.cells[x + 1][y].walls.wall_west = True
        elif direction == Direction.WEST:
            if x > 0:
                cell.walls.wall_west = True
                self._map.cells[x - 1][y].walls.wall_east = True

    def _left_of(self, heading):
        return (heading + 3) % 4

    def _right_of(self, heading):
        return (heading + 1) % 4

    # DAT--1 unknown neighbor tracking and frontier identification
    def _recompute_unknown_neighbors_all(self):
        for x in range(4):
            for y in range(8):
                self._map.cells[x][y].unknown_neighbor_count = self._count_unknown_neighbors(x, y)

    def _count_unknown_neighbors(self, x, y):
        count = 0
        for direction in (Direction.NORTH, Direction.EAST, Direction.SOUTH, Direction.WEST):
            dx, dy = direction_to_dx_dy(direction)
            nx = x + dx
            ny = y + dy
            if 0 <= nx < 4 and 0 <= ny < 8:
                cell = self._map.cells[x][y]
                if self._has_wall_between(x, y, nx, ny):
                    continue
                neighbor = self._map.cells[nx][ny]
                if neighbor.occupancy == OccupancyState.UNKNOWN:
                    count += 1
        return count

    def _has_wall_between(self, x1, y1, x2, y2):
        if not (0 <= x1 < 4 and 0 <= y1 < 8 and 0 <= x2 < 4 and 0 <= y2 < 8):
            return True
        dx = x2 - x1
        dy = y2 - y1
        if dx == 1 and dy == 0:
            return self._map.cells[x1][y1].walls.wall_east or self._map.cells[x2][y2].walls.wall_west
        if dx == -1 and dy == 0:
            return self._map.cells[x1][y1].walls.wall_west or self._map.cells[x2][y2].walls.wall_east
        if dx == 0 and dy == 1:
            return self._map.cells[x1][y1].walls.wall_north or self._map.cells[x2][y2].walls.wall_south
        if dx == 0 and dy == -1:
            return self._map.cells[x1][y1].walls.wall_south or self._map.cells[x2][y2].walls.wall_north
        # Non-adjacent cells - CMP--3 Failures
        return True

    # CMP--3: ExplorationProgressStatus (DAT--3)
    def get_exploration_progress_status(self, reachable_mask):
        # reachable_mask is 4x8 boolean list provided by planner BFS from current pose
        all_reachable_explored = True
        frontier_cells = []
        for x in range(4):
            for y in range(8):
                if not reachable_mask[x][y]:
                    continue
                cell = self._map.cells[x][y]
                if cell.occupancy == OccupancyState.FREE and cell.unknown_neighbor_count > 0:
                    frontier_cells.append((x, y))
                    all_reachable_explored = False
        return all_reachable_explored, frontier_cells

    # CMP--3: Second run evaluation support for CMP--6/CMP--10
    def evaluate_second_run_success(self, final_x, final_y):
        if not (0 <= final_x < 4 and 0 <= final_y < 8):
            return False, "OUT_OF_BOUNDS"
        cell = self._map.cells[final_x][final_y]
        if cell.occupancy != OccupancyState.FREE:
            return False, "FINAL_NOT_FREE"
        if not cell.is_goal_region:
            return False, "FINAL_NOT_GOAL_REGION"
        # Wall-constraint validation of path would use stored path; omitted for brevity.
        return True, "OK"

# SensorHardwareWrappers.
# Trace:
#   - CMP--11 SensorHardwareWrappers
#   - Uses Waveshare.ultrasonic_sensor.UltrasonicSensor
#   - Uses Waveshare.infrared.Infrared

from Waveshare.ultrasonic_sensor import UltrasonicSensor
from Waveshare.infrared import Infrared


class SensorHardwareWrappers:
    def __init__(self):
        self._ultrasonic = UltrasonicSensor()
        self._infrared = Infrared()

    # CMP--11 Execution
    def get_front_ultrasonic_distance_cm(self):
        # Wrapper to hardware; units are centimeters (CMP--11 Invariants)
        try:
            return self._ultrasonic.distance()
        except Exception:
            return None

    def get_ir_left_status(self):
        try:
            return 1 if self._infrared.dsl() else 0
        except Exception:
            return 0

    def get_ir_right_status(self):
        try:
            return 1 if self._infrared.dsr() else 0
        except Exception:
            return 0

# MotorHardwareInterface.
# Trace:
#   - CMP--12 MotorHardwareInterface
#   - Uses Waveshare.motor.Motor

from Waveshare.motor import Motor


class MotorHardwareInterface:
    def __init__(self, logger):
        self._logger = logger
        self._motor = Motor()

    # CMP--12 Execution: apply speed commands
    def motor_set(self, left_speed, right_speed):
        # Clamp to 0..100 per CMP--12 Invariants
        if left_speed < 0:
            left_speed = 0
        if right_speed < 0:
            right_speed = 0
        if left_speed > 100:
            left_speed = 100
        if right_speed > 100:
            right_speed = 100
        self._motor.set(left_speed, right_speed)

    def stop(self):
        self._motor.stop()

# SecondRunResultEvaluatorAndReporter.
# Trace:
#   - CMP--10 SecondRunResultEvaluatorAndReporter

class SecondRunResultEvaluatorAndReporter:
    def __init__(self, map_manager, logger):
        self._map_manager = map_manager
        self._logger = logger
        self._run_controller = None

    def set_run_controller(self, run_ctrl):
        self._run_controller = run_ctrl

    def on_second_run_completed(self, final_x, final_y, success, reason):
        if success:
            self._logger.log(
                "Second run SUCCESS at (%d,%d) reason=%s" % (final_x, final_y, reason),
                component="CMP--10",
            )
        else:
            self._logger.log(
                "Second run FAILURE at (%d,%d) reason=%s" % (final_x, final_y, reason),
                component="CMP--10",
            )
